type ModuleLink = {
  href: string;
  title: string;
  description: string;
};

function CycleMetaStrip({
  cycle,
  competitionId,
}: {
  cycle: CompetitionOut;
  competitionId: string;
}) {
  const [copied, setCopied] = useState(false);
  const languages =
    cycle.languages && cycle.languages.length > 0
      ? cycle.languages.join(", ")
      : "—";

  async function copyId() {
    try {
      await navigator.clipboard.writeText(competitionId);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
    } catch {
      setCopied(false);
    }
  }

  return (
    <div className="space-y-3 border-b border-border pb-6">
      <p className="text-sm text-muted-foreground sm:text-base">
        {cycle.period?.start} → {cycle.period?.end} · {cycle.timeZone} ·{" "}
        {languages}
      </p>
      <div className="flex flex-wrap items-center gap-2">
        <code className="rounded-md bg-muted px-2 py-1 font-mono text-xs text-foreground sm:text-sm">
          {competitionId}
        </code>
        <Button
          type="button"
          variant="outline"
          size="sm"
          className="min-h-9"
          onClick={copyId}
        >
          {copied ? "Copied" : "Copy"}
        </Button>
      </div>
    </div>
  );
}

